TRUNCATE stores, suppliers, departments, products RESTART IDENTITY CASCADE;
SELECT setval(pg_get_serial_sequence('stores','id'),(SELECT max(id) FROM stores));
SELECT setval(pg_get_serial_sequence('products','id'),(SELECT max(id) FROM products));
SELECT setval(pg_get_serial_sequence('departments','id'),(SELECT max(id) FROM departments));
SELECT setval(pg_get_serial_sequence('suppliers','id'),(SELECT max(id) FROM suppliers));
SELECT setval(pg_get_serial_sequence('store_products','id'),(SELECT max(id) FROM store_products));
SELECT setval(pg_get_serial_sequence('supplier_products','id'),(SELECT max(id) FROM supplier_products));
